    const MessageBubble = ({ 
      message, 
      onTextSelection, 
      selectedText, 
      selectionContext, 
      onCreateThread, 
      onCreateSelectedThread,
      siblingThreads,
      suggestedThreads,
      onCreateSuggestedThread,
      threadDropdown,
      onToggleDropdown,
      onNavigateToThread
    }) => {
      return (
        <div className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
          <div
            className={`max-w-3xl px-4 py-3 rounded-2xl ${
              message.sender === 'user'
                ? 'bg-blue-600 text-white'
