                                <div className="text-sm font-medium text-gray-900 flex items-center space-x-2">
                                  <GitBranch className="w-4 h-4" />
                                  <span>Related Threads ({siblingThreads.length})</span>
                                </div>
                              </div>
                              {siblingThreads.map(thread => (
                                <button
                                  key={thread.id}
